function r(a,n){if(!n)return"-";const e=a.find(t=>t.id===n);return e?.label||e?.name||`#${n}`}function u(a,n){return a.find(e=>e.id===n)?.name??(n?`#${n}`:"-")}function l(a,n){return a.filter(e=>e.plugin_id===n).map(e=>({value:e.id,label:e.base_url?`${e.name} · ${e.base_url}`:e.name}))}function f(a){return a.map(n=>({value:n.ID,label:`${n.Scheme}://${n.Host}:${n.Port}`}))}export{l as a,f as b,u as i,r as p};
